// Fake Prisma client (spec 020 testing): just enough surface — a class with
// $use middleware and query methods that run the pipeline. The hook must
// wrap this class when loaded under collectors and leave it native otherwise.
// FAKE_PRISMA_NO_USE=1 exports a client without $use to exercise the hook's
// graceful degradation (one notice, db counting off, http still recorded).
class PrismaClient {
	constructor() {
		this.middleware = [];
	}
	$use(fn) {
		this.middleware.push(fn);
	}
	_run(model, action) {
		const params = { model, action };
		let result = "ok";
		for (const fn of this.middleware) {
			result = fn(params, async () => result);
		}
		return result;
	}
	userFindMany() {
		return this._run("User", "findMany");
	}
	rawQuery() {
		return this._run(null, "queryRaw");
	}
}

class NoUseClient {
	userFindMany() {
		return Promise.resolve("ok");
	}
	rawQuery() {
		return Promise.resolve("ok");
	}
}

module.exports = {
	PrismaClient: process.env.FAKE_PRISMA_NO_USE === "1" ? NoUseClient : PrismaClient,
};
